<template>
  <q-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue', $event)">
    <q-card class="detail-card">
      <q-toolbar class="toolbar"><div class="header-icon"><q-icon name="fact_check" size="25px"/></div><q-toolbar-title><div class="title">Detalle de inventario <span>{{ inventario?.codigo }}</span></div><div class="subtitle">Información y trazabilidad del conteo físico</div></q-toolbar-title><q-badge :color="colorEstado" :label="textoEstado"/><q-btn flat round dense icon="close" class="q-ml-md" v-close-popup/></q-toolbar>
      <q-card-section class="content">
        <div class="section-title">Información general</div>
        <div class="info-grid"><div><span>Tipo</span><b>{{ inventario?.tipoLabel || '--' }}</b></div><div><span>Estado</span><b>{{ textoEstado }}</b></div><div><span>Fecha programada</span><b>{{ inventario?.fecha || '--' }}</b></div><div><span>Responsable</span><b>{{ inventario?.responsable || '--' }}</b></div><div><span>Almacén</span><b>{{ inventario?.almacen || '--' }}</b></div><div><span>Ubicación</span><b>{{ inventario?.ubicacion || '--' }}</b></div><div><span>Categoría</span><b>{{ inventario?.categoria || '--' }}</b></div><div><span>Conteo ciego</span><b>{{ inventario?.conteoCiego ? 'Activado' : 'Desactivado' }}</b></div></div>
        <q-banner v-if="inventario?.observacion" rounded class="observation q-mt-lg"><b>Observación:</b> {{ inventario.observacion }}</q-banner>
        <div class="section-title q-mt-xl">Resumen del conteo</div>
        <div class="summary row q-col-gutter-md"><div v-for="item in resumen" :key="item.label" class="col-6 col-md-3"><q-card flat bordered class="summary-card"><q-card-section><span>{{ item.label }}</span><b>{{ item.value }}</b></q-card-section></q-card></div></div>
        <div class="section-title q-mt-xl">Trazabilidad</div>
        <q-timeline color="green-8" layout="dense"><q-timeline-entry v-if="inventario?.fechaCreacion" title="Inventario creado" :subtitle="formatearFecha(inventario.fechaCreacion)" icon="add_task"><div>Registrado por {{ inventario.creadoPor || 'el usuario del sistema' }}.</div></q-timeline-entry><q-timeline-entry v-if="inventario?.fechaInicio" title="Conteo iniciado" :subtitle="formatearFecha(inventario.fechaInicio)" icon="fact_check"><div>Se generó la fotografía del stock.</div></q-timeline-entry><q-timeline-entry v-if="inventario?.fechaFinalizacion" title="Conteo finalizado" :subtitle="formatearFecha(inventario.fechaFinalizacion)" icon="done_all"><div>El inventario pasó a revisión.</div></q-timeline-entry><q-timeline-entry v-if="inventario?.fechaAprobacion" title="Inventario aprobado" :subtitle="formatearFecha(inventario.fechaAprobacion)" icon="verified"><div>Las diferencias fueron aplicadas al stock y Kardex.</div></q-timeline-entry></q-timeline>
        <div class="section-title q-mt-xl">Productos incluidos</div>
        <q-table flat bordered :rows="inventario?.detalles || []" :columns="columns" row-key="idDetalle" :rows-per-page-options="[5, 10, 20]" rows-per-page-label="Registros por página"><template #body-cell-producto="p"><q-td :props="p"><b>{{ p.row.producto }}</b><div class="muted">{{ p.row.codigoProducto }}</div></q-td></template><template #body-cell-diferencia="p"><q-td :props="p"><q-badge v-if="p.row.diferencia != null" :color="p.row.diferencia < 0 ? 'red-6' : p.row.diferencia > 0 ? 'blue-6' : 'green-7'" :label="p.row.diferencia > 0 ? `+${p.row.diferencia}` : `${p.row.diferencia}`"/><span v-else>--</span></q-td></template><template #no-data><div class="full-width text-center q-pa-lg text-grey-6">Todavía no existen líneas de conteo.</div></template></q-table>
      </q-card-section>
      <q-card-actions align="right" class="actions"><q-btn flat no-caps label="Cerrar" v-close-popup/><q-btn v-if="inventario?.estado === 'APROBADO'" unelevated no-caps color="green-8" icon="picture_as_pdf" label="Descargar acta" @click="$emit('pdf', inventario)"/></q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script setup>
import { computed } from 'vue'
const props = defineProps({ modelValue: Boolean, inventario: Object })
defineEmits(['update:modelValue', 'pdf'])
const colorEstado = computed(() => ({ BORRADOR: 'grey-7', EN_CONTEO: 'blue-7', EN_REVISION: 'amber-8', APROBADO: 'green-7', CANCELADO: 'red-6' }[props.inventario?.estado] || 'grey-6'))
const textoEstado = computed(() => props.inventario?.estado?.replaceAll('_', ' ') || '--')
const resumen = computed(() => { const r = props.inventario?.resumen || {}; return [{ label: 'Total líneas', value: r.total ?? props.inventario?.totalLineas ?? 0 }, { label: 'Contadas', value: r.contados ?? 0 }, { label: 'Pendientes', value: r.pendientes ?? 0 }, { label: 'Diferencias', value: r.diferencias ?? 0 }] })
const columns = [{ name: 'producto', label: 'Producto', field: 'producto', align: 'left' }, { name: 'lote', label: 'Lote', field: 'lote', align: 'left' }, { name: 'ubicacion', label: 'Ubicación', field: 'ubicacion', align: 'left' }, { name: 'cantidadSistema', label: 'Sistema', field: 'cantidadSistema', align: 'center' }, { name: 'cantidadFisica', label: 'Físico', field: 'cantidadFisica', align: 'center' }, { name: 'diferencia', label: 'Diferencia', field: 'diferencia', align: 'center' }]
const formatearFecha = value => value ? new Date(value).toLocaleString('es-BO') : '--'
</script>

<style scoped>
.detail-card{width:min(1100px,96vw);max-width:1100px;max-height:94vh;display:flex;flex-direction:column;border:1px solid #dce8d8;border-radius:22px;background:#f7faf6;font-family:'Nunito',sans-serif;box-shadow:0 22px 60px rgba(38,72,31,.2)}
.toolbar{min-height:86px;padding:0 24px;background:linear-gradient(135deg,#eaf7e3 0%,#fff 78%);border-bottom:1px solid #d8e5d3}.header-icon{width:50px;height:50px;border-radius:15px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#8acb4e,#438526);margin-right:14px;box-shadow:0 7px 16px rgba(67,133,38,.24)}.title{font-size:20px;font-weight:900;letter-spacing:-.2px;color:#243323}.title span{display:inline-block;margin-left:6px;color:#4a8c25}.subtitle{margin-top:3px;font-size:11px;color:#7b857c}
.content{overflow:auto;padding:26px}.section-title{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:900;color:#354634;margin:4px 0 14px}.info-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.info-grid div{min-height:62px;display:flex;justify-content:center;flex-direction:column;gap:5px;padding:12px 14px;border:1px solid #e1eadf;border-radius:12px;background:#fff;box-shadow:0 3px 10px rgba(62,96,52,.04)}.info-grid span,.summary-card span,.muted{font-size:11px;color:#7b857c}.info-grid b{font-size:13px;line-height:1.25;color:#263827}.observation{background:#fff8e8;color:#775817;border:1px solid #f1dfb2;box-shadow:0 3px 10px rgba(120,88,23,.05)}
.summary-card{height:100%;border-radius:15px;border-color:#dfe7dc;background:#fff;box-shadow:0 4px 14px rgba(62,96,52,.06)}.summary-card section{display:flex;flex-direction:column;gap:6px;padding:15px 16px}.summary-card b{font-size:24px;line-height:1;color:#356d20}.q-table{border-radius:15px;border-color:#dfe7dc;background:#fff;box-shadow:0 4px 14px rgba(62,96,52,.05)}.q-table :deep(thead tr){background:#eef8e9}.q-table :deep(th){height:48px;font-weight:900;color:#3f5140}.q-table :deep(tbody td){height:54px;border-color:#edf2eb}.q-table :deep(tbody tr:hover){background:#f8fcf6}.actions{padding:15px 24px;background:#fff;border-top:1px solid #dfe7dc;box-shadow:0 -5px 18px rgba(45,73,38,.06)}
@media(max-width:800px){.info-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.detail-card{width:100vw;max-height:100vh;border-radius:0}.content{padding:16px}.toolbar{padding:0 14px}.toolbar .q-badge{display:none}.title{font-size:17px}.info-grid{gap:8px}.info-grid div{padding:10px}.actions{padding:12px 14px}}
</style>
